CREATE OR REPLACE PROCEDURE dbp_macro.m_ups_bis_einkaeufer_ldap_zu(IN MANDANT_ID FLOAT64, IN MA_LDAP STRING, IN EINKAEUFER_BIS_ID STRING, IN HAT_EINKAEUFER_GRP_FG FLOAT64, IN EIGENE_GRUPPE_FG FLOAT64)
BEGIN
DECLARE sql_stmt STRING;
DECLARE sql_commit STRING;
BEGIN TRANSACTION;
SET sql_stmt  =  '''MERGE INTO dbp_security.bis_einkaeufer_ldap_zu AS TARGET USING (SELECT @MANDANT_ID AS mandant_id,   @MA_LDAP AS ma_ldap,   @EINKAEUFER_BIS_ID AS einkaeufer_bis_id,   @EIGENE_GRUPPE_FG AS eigene_gruppe_fg) AS source ON TARGET.mandant_id = source.mandant_id AND TARGET.ma_ldap = source.ma_ldap AND TARGET.einkaeufer_bis_id = source.einkaeufer_bis_id    WHEN MATCHED THEN UPDATE SET  eigene_gruppe_fg = CAST(CASE    WHEN @EIGENE_GRUPPE_FG_1 IS NULL    THEN 0    ELSE @EIGENE_GRUPPE_FG_1_2    END AS INTEGER) WHEN NOT MATCHED THEN INSERT (mandant_id, ma_ldap, einkaeufer_bis_id, eigene_gruppe_fg) VALUES(CAST(@MANDANT_ID_1 AS INTEGER)  , @MA_LDAP_1, @EINKAEUFER_BIS_ID_1, CAST(CASE    WHEN @EIGENE_GRUPPE_FG_1_2_3 IS NULL    THEN 0    ELSE @EIGENE_GRUPPE_FG_1_2_3_4    END AS INTEGER)) ''';

EXECUTE IMMEDIATE (sql_stmt) USING MANDANT_ID AS MANDANT_ID,  MA_LDAP AS MA_LDAP,  EINKAEUFER_BIS_ID AS EINKAEUFER_BIS_ID,  EIGENE_GRUPPE_FG AS EIGENE_GRUPPE_FG,  EIGENE_GRUPPE_FG AS EIGENE_GRUPPE_FG_1,  EIGENE_GRUPPE_FG AS EIGENE_GRUPPE_FG_1_2,  MANDANT_ID AS MANDANT_ID_1,  MA_LDAP AS MA_LDAP_1,  EINKAEUFER_BIS_ID AS EINKAEUFER_BIS_ID_1,  EIGENE_GRUPPE_FG AS EIGENE_GRUPPE_FG_1_2_3,  EIGENE_GRUPPE_FG AS EIGENE_GRUPPE_FG_1_2_3_4;

SET sql_stmt  =  '''DELETE FROM dbp_security.bis_einkaeufer_ldap_zu WHERE @HAT_EINKAEUFER_GRP_FG IN (0) AND mandant_id= @MANDANT_ID AND ma_ldap= @MA_LDAP AND einkaeufer_bis_id= @EINKAEUFER_BIS_ID ''';

EXECUTE IMMEDIATE (sql_stmt) USING MANDANT_ID AS MANDANT_ID,  MA_LDAP AS MA_LDAP,  EINKAEUFER_BIS_ID AS EINKAEUFER_BIS_ID,  HAT_EINKAEUFER_GRP_FG AS HAT_EINKAEUFER_GRP_FG;

SET sql_commit  =  'COMMIT TRANSACTION';

EXECUTE IMMEDIATE (sql_commit);
END;

